import React, { useState, useEffect } from "react";
import "./Seo.css";
import { useLocation } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFileLines, faClosedCaptioning, faSearch, faImage } from "@fortawesome/free-solid-svg-icons";
import { fetchVideoMetadata } from "../axios-use/api";

function SEO({ videoThumbnail }) {
  const location = useLocation();
  const { message, results = {}, videoURL } = location.state || {};
  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");
  const [displayVideo, setDisplayVideo] = useState(null);
  const [thumbnail, setThumbnail] = useState(videoThumbnail || "https://via.placeholder.com/300x300");

  const seoData = results?.seo || {};
  const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
  const description = seoData.description || "No description available.";
  const title = seoData.title || "No title available.";
  const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

  // Save paths for video upscaling and audio processing
  const videoUpscalingPath = results?.video_upscaling?.output_path || null;
  const audioProcessingPath = results?.audio_processing?.output_path || null;

  useEffect(() => {
    const fetchMedia = async () => {
      try {
        console.log(results)
        if (audioProcessingPath) {
          // Use audio-enhanced video
          setDisplayVideo(`http://127.0.0.1:8000/media/${audioProcessingPath}`);
        } else if (videoUpscalingPath) {
          // Use video-enhanced output
          setDisplayVideo(`http://127.0.0.1:8000/media/${videoUpscalingPath}`);
        } else if (videoURL) {
          // Fetch thumbnail if no enhanced video is available
          const data = await fetchVideoMetadata(videoURL);
          setThumbnail(data.thumbnail); // Assuming the metadata contains a `thumbnail` property
        }
      } catch (error) {
        console.error("Error fetching video or thumbnail:", error);
      }
    };

    fetchMedia();
  }, [audioProcessingPath, videoUpscalingPath, videoURL]);

  return (
    <div className="seo-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content Section */}
      <main className="main-content">
        {/* Navigation to Clipper */}
        <button className="clipper-btn">Go to Clipper</button>

        {/* Clip Section */}
        <div className="clip-section">
          {/* Media Preview */}
          <div className="media-preview">
            {displayVideo ? (
              <video
                src={displayVideo}
                controls
                className="preview-video"
                alt="Enhanced Video"
              />
            ) : (
              <img
                src={thumbnail}
                alt="Video Thumbnail"
                className="preview-image"
              />
            )}
          </div>

          {/* Clip Customization */}
          <div className="customize-clip">
            {/* SEO Data Display */}
            <div className="seo-data">
              <div className="seo-box">
                <h2>Keywords</h2>
                <p>{keywords}</p>
              </div>
              <div className="seo-box">
                <h2>Description</h2>
                <p>{description}</p>
              </div>
              <div className="seo-box">
                <h2>Title</h2>
                <p>{title}</p>
              </div>
              <div className="seo-box">
                <h2>Tags</h2>
                <p>{tags}</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default SEO;
